output_text:
[
  {
    "id": "no_carts_in_single_file_aisles",
    "text": "Shopping carts are prohibited in single-file shelf aisles.",
    "abstraction": {
      "state_properties": {
        "singleFileAisle": {
          "le": [
            "freeWidthH",
            1
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "singleFileAisle"
        ]
      }
    }
  },
  {
    "id": "do_not_enter_single_file_with_cart",
    "text": "An agent must not move from an open area into a single-file aisle while still pushing a cart.",
    "abstraction": {
      "state_properties": {
        "openArea": {
          "gt": [
            "freeWidthH",
            1
          ]
        },
        "singleFileAisle": {
          "le": [
            "freeWidthH",
            1
          ]
        },
        "moveAction": {
          "or": [
            "N",
            "S",
            "E",
            "W"
          ]
        }
      },
      "events": {
        "enterSingleFileWithCart": {
          "pre": {
            "and": [
              "hasCart",
              "openArea",
              "moveAction"
            ]
          },
          "post": "singleFileAisle"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "enterSingleFileWithCart"
    }
  },
  {
    "id": "retrieve_cart_after_parking_at_aisle_mouth",
    "text": "After parking a cart at an aisle mouth, the agent is obliged to retrieve it before finishing the trip.",
    "abstraction": {
      "state_properties": {
        "aisleMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        },
        "parkedCartAtMouth": {
          "and": [
            "aisleMouth",
            {
              "not": "hasCart"
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "obligation",
      "trigger": "parkedCartAtMouth",
      "discharge": "hasCart"
    }
  },
  {
    "id": "cart_required_for_open_shelf_interaction",
    "text": "Shelf interactions in open cart-accessible aisles must be performed with a cart, while narrow single-file shelf aisles are exempt.",
    "abstraction": {
      "state_properties": {
        "openShelfZone": {
          "and": [
            "adjShelf",
            {
              "gt": [
                "freeWidthH",
                1
              ]
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "INTERACT",
          "openShelfZone",
          {
            "not": "hasCart"
          }
        ]
      }
    }
  },
  {
    "id": "interact_only_at_functional_locations",
    "text": "Interactions are only allowed at the cart station, at cart-parking aisle mouths, or next to shelves.",
    "abstraction": {
      "state_properties": {
        "cartStation": "at(1,7)",
        "aisleMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        },
        "functionalInteractionLocation": {
          "or": [
            "cartStation",
            "aisleMouth",
            "adjShelf"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "INTERACT",
          {
            "not": "functionalInteractionLocation"
          }
        ]
      }
    }
  },
  {
    "id": "single_file_aisles_are_north_south_only",
    "text": "In single-file aisles, agents must travel only north or south and may not move laterally.",
    "abstraction": {
      "state_properties": {
        "singleFileAisle": {
          "le": [
            "freeWidthH",
            1
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "singleFileAisle",
          {
            "or": [
              "E",
              "W"
            ]
          }
        ]
      }
    }
  },
  {
    "id": "wide_cart_aisles_are_one_way_east",
    "text": "When pushing a cart in wide horizontal aisles, agents must follow the one-way eastbound flow and not travel west.",
    "abstraction": {
      "state_properties": {
        "wideHorizontalCartAisle": {
          "and": [
            "hasCart",
            {
              "ge": [
                "freeWidthH",
                6
              ]
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "wideHorizontalCartAisle",
          "W"
        ]
      }
    }
  },
  {
    "id": "cart_transfer_only_at_handling_spots",
    "text": "Picking up or dropping off a cart is only allowed at the entrance cart station or at designated aisle-mouth parking spots.",
    "abstraction": {
      "state_properties": {
        "cartStation": "at(1,7)",
        "aisleMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        },
        "cartHandlingSpot": {
          "or": [
            "cartStation",
            "aisleMouth"
          ]
        }
      },
      "events": {
        "gainCart": {
          "pre": {
            "and": [
              "INTERACT",
              {
                "not": "hasCart"
              }
            ]
          },
          "post": "hasCart"
        },
        "dropCart": {
          "pre": {
            "and": [
              "INTERACT",
              "hasCart"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        },
        "cartTransfer": {
          "pre": {
            "or": [
              "gainCart",
              "dropCart"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "cartTransfer",
          {
            "not": "cartHandlingSpot"
          }
        ]
      }
    }
  }
]
